class Solution { int check(int target,vector<int>& tops,vector<int>& bottoms){int top=0,bottom=0;for(int i=0;i<(int)tops.size();++i){if(tops[i]!=target&&bottoms[i]!=target)return INT_MAX;if(tops[i]!=target)++top;if(bottoms[i]!=target)++bottom;}return min(top,bottom);}public:int minDominoRotations(vector<int>& tops,vector<int>& bottoms){int answer=min(check(tops[0],tops,bottoms),check(bottoms[0],tops,bottoms));return answer==INT_MAX?-1:answer;} };
